                      {'skill_id': 'attack', 'display_name': 'Attack', 'level': 75},
                      {'skill_id': 'construction', 'display_name': 'Construction', 'level': 50},
                      {'skill_id': 'cooking', 'display_name': 'Cooking', 'level': 48},
                      {'skill_id': 'crafting', 'display_name': 'Crafting', 'level': 60},
